import React, { useState, useEffect } from "react";
import axios from "axios";
import QuestionCard from "./component/QuestionCard";
import "./App.css";

function App() {
  const [questions, setQuestions] = useState([]);
  const [hideAnswers, setHideAnswers] = useState(false);

  const createEmptyForm = () => [
    { question: "", answer: "", confirmAnswer: "" },
    { question: "", answer: "", confirmAnswer: "" },
    { question: "", answer: "", confirmAnswer: "" },
    { question: "", answer: "", confirmAnswer: "" },
    { question: "", answer: "", confirmAnswer: "" }
  ];

  const [qaList, setQaList] = useState(createEmptyForm());

  useEffect(() => {
    const fetchQuestions = async () => {
      try {
        const response = await axios.get("http://localhost:3001/questions");
        // Log exactly what comes back to the console
        console.log("Server Response:", response.data);

        // Ensure we are setting an array
        const data = Array.isArray(response.data) ? response.data : [];
        setQuestions(data);
      } catch (err) {
        console.error("Failed to connect to backend:", err);
      }
    };
    fetchQuestions();
  }, []);

  const handleUpdate = (index, field, value) => {
    const updated = [...qaList];
    updated[index][field] = value;
    setQaList(updated);
  };

  const getFilteredList = (currentIndex) => {
    const otherSelections = qaList
      .filter((_, idx) => idx !== currentIndex)
      .map(item => item.question);

    return questions.filter(q => !otherSelections.includes(q.question));
  };

  const handleSubmit = async () => {
    if (qaList.some(q => !q.question || !q.answer)) {
      return alert("Please fill all fields.");
    }
    try {
      await axios.post("http://localhost:3001/responses", { responses: qaList });
      alert("Submitted!");
      setQaList(createEmptyForm());
    } catch (err) {
      alert("Error saving data.");
    }
  };

  return (
    <div className="app-container">
      <div className="toggle-box">
        <label>
          <input type="checkbox" onChange={() => setHideAnswers(!hideAnswers)} /> Hide Answers
        </label>
      </div>
      <h1 className="title">Security Setup</h1>
      <div className="form-container">
        {qaList.map((qa, i) => (
          <QuestionCard
            key={i}
            index={i}
            qa={qa}
            questions={getFilteredList(i)}
            hideAnswers={hideAnswers} 
            onChange={handleUpdate}
          />
        ))}
        <button className="submit-btn" onClick={handleSubmit}>Submit All</button>
      </div>
    </div>
  );
}

export default App;
